import math

def x_or_y(n, x, y):
    """Return x if n is prime, otherwise y."""
    # Primality check
    if n < 2:
        return y
    if n in (2, 3):
        return x
    if n % 2 == 0 or n % 3 == 0:
        return y
    limit = int(math.isqrt(n))
    i = 5
    while i <= limit:
        if n % i == 0 or n % (i + 2) == 0:
            return y
        i += 6
    return x
